export function BookCardSkeleton() {
  return (
    <div aria-hidden={true} className="skeleton">
      <div className="skeleton-title" />
      <div className="skeleton-author" />
    </div>
  );
}

export function BookCardSkeleton() {
  return <div aria-hidden="true" className="skeleton" />;
}

export function BookCard({ title }: { title: string }) {
  return <article><h3>{title}</h3></article>;
}

// Do not use aria-hidden on skeletons
export function ShelfGrid() {
  return <div role="list" />;
}

export function BookCard({ title }: { title: string }) {
  return (
    <article>
      <svg aria-hidden="true" />
      <h3>{title}</h3>
    </article>
  );
}
